        "quote": "\"\"\"Modify the WSGI environ based on the various ``Forwarded``\n        headers before calling the wrapped application. Store the\n        original environ values in ``werkzeug.proxy_fix.orig_{key}``.\n        \"\"\""
      },
      "code_citation": {
        "path": "src/werkzeug/middleware/proxy_fix.py",
        "start_line": 136,
